#!/usr/bin/env bun
// Writes stage-frontmatter.ts beside this file: the stage frontmatter parser
// and validator a 2.11.0 tool runs over a newer release's stage files when it
// refreshes a project, taken from `git show v2.11.0:<file>` with two changes:
// comment-only lines are left out, and each character outside printable ASCII
// on a code line is written as its \u escape, so the copy is plain ASCII and
// every string means the same at run time. Run it by hand in a clone that has
// the release tags:
//
//   bun tests/fixtures/stage-frontmatter-2.11.0/generate.ts
//   bun tests/fixtures/stage-frontmatter-2.11.0/generate.ts --hashes v2.8.0 v2.11.0
//
// The second form prints, per tag, the hash of each function the test pins.
import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import { writeFileSync } from "node:fs";
import { join } from "node:path";

const TAG = "v2.11.0";
const LIB_FUNCTIONS = [
  "isPlainObject",
  "scalarField",
  "listField",
  "parseStageFrontmatter",
  "mapOfListsField",
  "objectListField",
  "coerceScalar",
  "unquoteScalar",
  "parseInlineDepsList",
];
export const PINNED_FUNCTIONS = ["parseStageFrontmatter", "objectListField", "validateStageFrontmatter"];
export const MARKER = "// ---- copied from v2.11.0 below this line ----";

function show(tag: string, path: string): string {
  const shown = spawnSync("git", ["show", `${tag}:${path}`], { encoding: "utf-8", maxBuffer: 64 * 1024 * 1024 });
  if (shown.status !== 0) throw new Error(`git show ${tag}:${path}: ${shown.stderr}`);
  return shown.stdout.replace(/\r\n/g, "\n");
}

const COMMENT_ONLY = /^\s*(?:\/\/|\/\*|\*)/;
const BACKSLASH = String.fromCharCode(92);

function plain(text: string): string {
  return text
    .split("\n")
    .filter((line) => !COMMENT_ONLY.test(line))
    .map((line) =>
      [...line]
        .map((char) => {
          const code = char.codePointAt(0) ?? 0;
          return code > 0x7e ? `${BACKSLASH}u${code.toString(16).padStart(4, "0")}` : char;
        })
        .join("")
    )
    .join("\n");
}

/** A top-level declaration of `name` from its first line through the first line that is exactly `}` or `};` (or the line itself when it ends with `;`). */
export function declaration(text: string, name: string): string {
  const start = new RegExp(`^(?:export )?(?:function ${name}\\(|const ${name}\\b)`, "m").exec(text);
  if (!start) throw new Error(`no top-level ${name}`);
  const line = text.slice(start.index, text.indexOf("\n", start.index));
  if (line.endsWith(";")) return line;
  const close = /\n\};?\n/g;
  close.lastIndex = start.index;
  const end = close.exec(text);
  if (!end) throw new Error(`${name} has no closing line`);
  return text.slice(start.index, end.index + end[0].length - 1);
}

export function hash(text: string): string {
  return createHash("sha256").update(text).digest("hex");
}

function copied(tag: string): string {
  const lib = show(tag, "core/tools/aidlc-lib.ts");
  const vocabulary = show(tag, "core/tools/aidlc-artifact-vocabulary.ts");
  const schema = show(tag, "core/tools/aidlc-stage-schema.ts")
    .replace(/^import \{[^}]*\} from "\.\/aidlc-lib\.ts";\n/m, "");
  const parts = [
    declaration(vocabulary, "ARTIFACT_FILENAMES"),
    declaration(vocabulary, "artifactFilename"),
    declaration(lib, "UNIT_KINDS"),
    ...LIB_FUNCTIONS.map((name) => declaration(lib, name)),
    schema,
  ];
  return plain(parts.join("\n\n")).replace(/\n{3,}/g, "\n\n").trimEnd();
}

const HEADER = [
  "// Generated by generate.ts beside this file; do not edit by hand.",
  "// The stage frontmatter parser and validator of AI-DLC 2.11.0, as a 2.8.0 to",
  "// 2.11.0 tool runs them over a newer release's stage files while it",
  "// refreshes a project: core/tools/aidlc-lib.ts parseStageFrontmatter and the",
  "// readers it calls, artifactFilename, UNIT_KINDS, and the whole of",
  "// core/tools/aidlc-stage-schema.ts, with comment-only lines left out and",
  "// characters outside printable ASCII written as escapes.",
].join("\n");

if (import.meta.main) {
  const args = process.argv.slice(2);
  if (args[0] === "--hashes") {
    for (const tag of args.slice(1)) {
      const text = copied(tag);
      console.log(`${tag}\t${PINNED_FUNCTIONS.map((name) => `${name}=${hash(declaration(text, name))}`).join("\t")}`);
    }
  } else {
    const body = copied(TAG);
    writeFileSync(join(import.meta.dir, "stage-frontmatter.ts"), `${HEADER}\n${MARKER}\n${body}\n`);
    console.log(`wrote stage-frontmatter.ts from ${TAG}; body sha256 ${hash(`${body}\n`)}`);
  }
}
